test('a download that the server answers with an error page shows that error', async () => {
    const current = execution();
    current.controller.submit();
    await settle();
    captureDownloads(current);
    current.target.querySelector('.query-result-download-button').trigger('click');
    const frame = current.document.body.querySelectorAll('iframe')[0];
    assert.ok(frame, 'downloads go to a hidden frame');
    const notice = current.target.querySelector('.query-result-download-error');
    assert.ok(notice, 'the download pane has a place for download errors');
    frame.contentDocument = { body: { textContent: '' } };
    frame.trigger('load');
    assert.equal(notice.textContent, '', 'an empty frame (a started download) is no error');
    frame.contentDocument = { body: { textContent: '  HTTP Status 403 – Forbidden  ' } };
    frame.trigger('load');
    assert.match(notice.textContent, /Download failed: HTTP Status 403 – Forbidden/);
    assert.equal(notice.hidden, false);
    current.target.querySelector('.query-result-download-button').trigger('click');
    assert.equal(notice.textContent, '', 'a new download clears the previous error');
    current.controller.dispose();
});

function heldQueryServer(window) {
    const releases = [];
    const records = [
        { type: 'head', version: 1 }, { type: 'view', id: 'tuple' }, { type: 'vars', values: ['item'] },
        { type: 'rows', values: [[{ kind: 'literal', value: 'row' }]] },
        { type: 'end', metadata: { 'result-offset': 0, 'result-limit': 1000000, 'result-batch-count': 1,
            'result-has-more': false, 'result-next-offset': 1 } }
    ].map(record => JSON.stringify(record) + '\n').join('');
    window.fetch = async (url, options) => {
        if (String(options && options.body || '').includes('action=cancel-query')) {
            return { ok: true, status: 204 };
        }
        const held = new Promise(resolve => releases.push(resolve));
        let delivered = false;
        return { ok: true, status: 200, body: { getReader: () => ({
            read: async () => {
                if (delivered) return { done: true };
                await held;
                delivered = true;
                return { done: false, value: new TextEncoder().encode(records) };
            },
            cancel: async () => {}
        }) } };
    };
    return releases;
}

// Review finding B5: a result waiting for its repository's next Query page (shelved) that finishes out of sight must
// not touch the Query page that is shown, which may be rendered into the same elements.
test('a shelved query that finishes leaves the shown Query page\'s Cancel, request id and busy state alone', async () => {
    const { workbench, document, window } = require('./query-load-more-harness.js').loadApi();
    const releases = heldQueryServer(window);
    const form = document.createElement('form');
    form.setAttribute('id', 'query-form');
    form.setAttribute('action', 'query');
    const query = document.createElement('textarea');
    query.name = 'query';
    query.value = 'SELECT ?item WHERE { VALUES ?item { "row" } }';
    form.appendChild(query);
    const requestId = document.createElement('input');
    requestId.name = 'query-request-id';
    requestId.type = 'hidden';
    form.appendChild(requestId);
    const cancelButton = document.createElement('button');
    cancelButton.setAttribute('id', 'query-cancel');
    cancelButton.disabled = true;
    form.appendChild(cancelButton);
    const target = document.createElement('section');
    target.setAttribute('id', 'query-results');
    document.body.appendChild(form);
    document.body.appendChild(target);
    const { MemoryWorker } = require('./query-load-more-harness.js');
    const render = (repositoryId) => workbench.queryPage.renderInto(document.body, {}, {
        executionFormId: 'query-form', resultsMountId: 'query-results', repositoryId,
        rowStoreOptions: { workerFactory: () => new MemoryWorker() }
    });

    const first = render('repo-a');
    form.trigger('submit');
    await settle();
    assert.equal(releases.length, 1, 'repo-a runs');
    first('navigate');
    assert.equal(workbench.queryPage.activity('repo-a'), 'running', 'it waits, running, for its next Query page');

    // The next Query page (another repository) is rendered into the same elements and runs its own query.
    const second = render('repo-b');
    form.trigger('submit');
    await settle();
    assert.equal(releases.length, 2, 'repo-b runs');
    const shownRequest = requestId.value;
    assert.ok(shownRequest);
    assert.equal(cancelButton.disabled, false);
    assert.equal(target.getAttribute('aria-busy'), 'true');

    releases[0]();
    await settle();
    assert.equal(workbench.queryPage.activity('repo-a'), 'ready');
    assert.equal(cancelButton.disabled, false, 'the shown query can still be cancelled');
    assert.equal(requestId.value, shownRequest, 'the shown query keeps its request id');
    assert.equal(target.getAttribute('aria-busy'), 'true', 'the shown results area is still busy');

    releases[1]();
    await settle();
    assert.equal(cancelButton.disabled, true);
    assert.equal(target.getAttribute('aria-busy'), 'false');
    second();
});

// Round 2 (R4): the shelved result must also give back the busy state it set on the results area when it leaves,
// or the next Query page rendered into the same elements shows an endless progress bar.
test('a query shelved while it runs leaves its results area idle for the next Query page', async () => {
    const { workbench, document, window } = require('./query-load-more-harness.js').loadApi();
    const releases = heldQueryServer(window);
    const form = document.createElement('form');
    form.setAttribute('id', 'query-form');
    form.setAttribute('action', 'query');
    const query = document.createElement('textarea');
    query.name = 'query';
    query.value = 'SELECT ?item WHERE { VALUES ?item { "row" } }';
    form.appendChild(query);
    const target = document.createElement('section');
    target.setAttribute('id', 'query-results');
    target.setAttribute('aria-busy', 'false');
    const loading = document.createElement('div');
    loading.setAttribute('id', 'query-results-loading');
    loading.hidden = true;
    target.appendChild(loading);
    document.body.appendChild(form);
    document.body.appendChild(target);
    const { MemoryWorker } = require('./query-load-more-harness.js');
    const render = (repositoryId) => workbench.queryPage.renderInto(document.body, {}, {
        executionFormId: 'query-form', resultsMountId: 'query-results', repositoryId,
        rowStoreOptions: { workerFactory: () => new MemoryWorker() }
    });

    const first = render('repo-a');
    form.trigger('submit');
    await settle();
    assert.equal(target.getAttribute('aria-busy'), 'true');
    assert.equal(loading.hidden, false);
    first('navigate');
    assert.equal(workbench.queryPage.activity('repo-a'), 'running');
    assert.equal(target.getAttribute('aria-busy'), 'false', 'the area the running result left is not busy');
    assert.equal(loading.hidden, true, 'and shows no loading line');

    const second = render('repo-b');
    releases[0]();
    await settle();
    assert.equal(workbench.queryPage.activity('repo-a'), 'ready');
    assert.equal(target.getAttribute('aria-busy'), 'false', 'the shown page stays idle when the shelved one ends');
    assert.equal(loading.hidden, true);
    second();
});

// Review finding B23: the saved-query list is virtualized; a card that scrolls out of the row window loses its form.
test('a running saved query survives its card scrolling out of the list window and comes back with it', async () => {
    const { api, document, window, MemoryWorker } = Object.assign(require('./query-load-more-harness.js').loadApi(),
        { MemoryWorker: require('./query-load-more-harness.js').MemoryWorker });
    const releases = heldQueryServer(window);
    const requests = [];
    const fetcher = (url, init) => { requests.push({ url, init }); return window.fetch(url, init); };
    function card(index, name) {
        const form = document.createElement('form');
        form.setAttribute('id', 'saved-query-exec-' + index);
        form.setAttribute('method', 'post');
        form.setAttribute('action', 'query');
        form.setAttribute('data-workbench-query-execution', 'true');
        form.setAttribute('data-workbench-results-target', 'saved-query-results-' + index);
        for (const [controlName, value] of [['action', 'exec'], ['query', name], ['ref', 'id'], ['owner', 'alice']]) {
            const control = document.createElement('input');
            control.name = controlName;
            control.type = 'hidden';
            control.value = value;
            form.appendChild(control);
        }
        const target = document.createElement('section');
        target.setAttribute('id', 'saved-query-results-' + index);
        document.body.appendChild(form);
        document.body.appendChild(target);
        return { form, target, remove() { document.body.removeChild(form); document.body.removeChild(target); } };
    }
    let visible = [];
    const root = { ownerDocument: document, querySelectorAll: () => visible };
    const options = { fetcher, rowStoreOptions: { workerFactory: () => new MemoryWorker() } };

    const first = card(0, 'People');
    visible = [first.form];
    const dispose = api.bindExecutionForms(root, options);
    first.form.trigger('submit');
    await settle();
    assert.equal(requests.length, 1);

    // The card leaves the row window: the list renders without it.
    first.remove();
    visible = [];
    api.bindExecutionForms(root, options);
    assert.equal(first.form.listenerCount('submit'), 0, 'the old form is unbound');
    assert.equal(requests[0].init.signal.aborted, false, 'the running query is not cancelled');
    releases[0]();
    await settle();

    // It comes back as a new card element for the same saved query.
    const again = card(0, 'People');
    visible = [again.form];
    api.bindExecutionForms(root, options);
    await settle();
    assert.equal(requests.length, 1, 'the query is not run again');
    assert.match(again.target.textContent, /1 row · complete/, 'its result is shown in the new card');
    assert.equal(again.form.listenerCount('submit'), 1);

    // Another saved query never executed is just unbound and bound again.
    const other = card(1, 'Places');
    visible = [again.form, other.form];
    api.bindExecutionForms(root, options);
    other.remove();
    visible = [again.form];
    api.bindExecutionForms(root, options);
    dispose();
    assert.equal(again.form.listenerCount('submit'), 0);
});

function memoryRowStore() {
    let rows = [];
    return {
        async append(batch) { rows.push(...batch); return rows.length; },
        async read(start, count) { return rows.slice(start, start + count); },
        async count() { return rows.length; },
        async truncate(count) { rows.length = count; return count; },
        async dispose() { rows = []; }
    };
}

// Review finding B12: in the automatic layout the header widths were measured twice per frame (a computed style per
// header and a probe element with a forced layout per column); they only change with the headers or the font.
test('automatic layout measures the readable header widths once per header set and font', async () => {
    const { api, document, window } = require('./query-load-more-harness.js').loadApi();
    const getComputedStyle = window.getComputedStyle;
    let headerStyles = 0;
    window.getComputedStyle = (element) => {
        if (element && element.tagName === 'TH') headerStyles++;
        return getComputedStyle(element);
    };
    const target = document.createElement('section');
    document.body.appendChild(target);
    const renderer = new api.QueryResultRenderer(target, { rowStore: memoryRowStore(), initialLayout: 'auto' });
    let probes = 0;
    const appendChild = renderer.root.appendChild.bind(renderer.root);
    renderer.root.appendChild = (child) => {
        if (child && child.tagName === 'SPAN' || child && child.nodeType === 11) probes++;
        return appendChild(child);
    };
    await renderer.accept({ type: 'view', id: 'tuple' });
    await renderer.accept({ type: 'vars', values: ['subject', 'predicate', 'object'] });
    for (let chunk = 0; chunk < 5; chunk++) {
        await renderer.accept({ type: 'rows', values: [[{ kind: 'iri', value: 'urn:s' + chunk },
            { kind: 'iri', value: 'urn:p' }, { kind: 'literal', value: 'o' + chunk }]] });
        await settle();
    }
    await renderer.accept({ type: 'end', metadata: {} });
    await settle();
    assert.ok(headerStyles > 0, 'the headers were measured');
    assert.ok(headerStyles <= 3, 'each of the 3 headers is measured once, not per frame: ' + headerStyles);
    assert.ok(probes <= 1, 'the probes are added in one batch: ' + probes);
    renderer.dispose();
});

// Review finding B20: a viewport taller than the row cap left its first visible rows blank under the top spacer.
// Round 2 (R1): the cap is a hard bound on the rows in the document. More rows than the cap only seem visible while
// the row-height estimate is too small; the renderer raises the cap for really tall viewports (see windowCap and
// e2e/tests/workbench-round2-client.spec.js), so the window never grows with a wrong estimate.
test('the row window never exceeds its cap and starts at the first visible row when the cap is short', () => {
    const { api } = require('./query-load-more-harness.js').loadApi();
    const heights = new api.MeasuredRowHeights(1000, 10);
    const tall = heights.range(0, 1000, 4, 80);
    assert.equal(tall.start, 0, 'the first visible row is rendered');
    assert.equal(tall.end, 80, 'the window stops at the cap');
    assert.equal(tall.topSpacer, 0);

    const middle = heights.range(2000, 1000, 4, 80);
    assert.deepEqual([middle.start, middle.end], [200, 280], 'the top of the viewport is never left blank');
    assert.equal(middle.topSpacer, 2000);

    const onePixel = new api.MeasuredRowHeights(1000, 1).range(0, 1400, 4, 80);
    assert.equal(onePixel.end - onePixel.start, 80, 'a 1px estimate does not render one row per pixel');

    const end = heights.range(9000, 1000, 4, 80);
    assert.deepEqual([end.start, end.end], [920, 1000], 'scrolled to the end, the last rows stay in view');

    const overscan = heights.range(2000, 500, 40, 80);
    assert.ok(overscan.start <= 200 && overscan.end >= 250, 'visible rows stay in a capped window');
    assert.ok(overscan.end - overscan.start <= 80, 'only the overscan is cut to the cap');
    assert.equal(overscan.start, 186, 'the spare rows are shared on both sides');
    assert.equal(overscan.end, 266);
});

// Review finding B18: a query is cancelled at its own repository's endpoint, even after another page is shown.
test('cancelling a query posts to the endpoint it ran at, not one relative to the page shown now', async () => {
    const current = execution({ responses: [() => new Promise(() => {}), () => new Promise(() => {})] });
    current.form.setAttribute('action', 'query');
    current.document.location.href = 'http://localhost:8080/rdf4j-workbench/repositories/owned/query';
    const cancels = [];
    current.workbench.query = { cancelServerQuery: (id, url) => cancels.push([id, url]) };
    const keepalive = [];
    current.window.fetch = (url, init) => { keepalive.push({ url, init }); return Promise.resolve({ ok: true }); };
    current.controller.submit();
    await settle();
    current.document.location.href = 'http://localhost:8080/rdf4j-workbench/repositories/other/summary';

    assert.equal(current.controller.cancel(), true);
    assert.equal(cancels.length, 1);
    assert.equal(cancels[0][1], 'http://localhost:8080/rdf4j-workbench/repositories/owned/query');

    current.document.location.href = 'http://localhost:8080/rdf4j-workbench/repositories/owned/query';
    current.controller.submit();
    await settle();
    current.document.location.href = 'http://localhost:8080/rdf4j-workbench/repositories/other/summary';
    assert.equal(current.controller.cancelOnLeave(), true);
    assert.equal(keepalive.length, 1, 'a page being left sends one keepalive request');
    assert.equal(keepalive[0].url, 'http://localhost:8080/rdf4j-workbench/repositories/owned/query');
    assert.equal(keepalive[0].init.keepalive, true);
    current.controller.dispose();
});

/** Counts the characters indexOf scans in the realm of fn (the compiled script's own String.prototype). */
function countScans(fn) {
    const prototype = fn.constructor('return String.prototype')();
    const indexOf = prototype.indexOf;
    const counter = { scanned: 0, restore() { prototype.indexOf = indexOf; } };
    prototype.indexOf = function(search, from) {
        counter.scanned += Math.max(0, this.length - (from || 0));
        return indexOf.call(this, search, from);
    };
    return counter;
}

function oversizedRecordChunks(chunkSize) {
    const big = 'x'.repeat(2 * 1024 * 1024);
    const text = [
        JSON.stringify({ type: 'head', version: 1 }),
        JSON.stringify({ type: 'metadata', values: { big } }),
        JSON.stringify({ type: 'end' })
    ].join('\n') + '\n';
    const chunks = [];
    for (let start = 0; start < text.length; start += chunkSize) chunks.push(text.substring(start, start + chunkSize));
    return { text, chunks };
}

// Review finding B13: an oversized record arriving in many chunks was rescanned from its start for every chunk.
test('the NDJSON reader scans each chunk once, also for a record far larger than a chunk', async () => {
    const { api } = require('./query-load-more-harness.js').loadApi();
    const { text, chunks } = oversizedRecordChunks(16 * 1024);
    let index = 0;
    const response = { ok: true, status: 200, body: { getReader: () => ({
        async read() {
            return index < chunks.length ? { done: false, value: new TextEncoder().encode(chunks[index++]) }
                : { done: true };
        },
        async cancel() {}
    }) } };
    const seen = [];
    const counter = countScans(api.consumeNdjsonResponse);
    let outcome;
    try {
        outcome = await api.consumeNdjsonResponse(response, { onRecord: (record) => { seen.push(record.type); } });
    } finally {
        counter.restore();
    }
    assert.equal(outcome.type, 'end');
    assert.deepEqual(seen, ['head', 'metadata', 'end']);
    assert.ok(counter.scanned < 3 * text.length,
        'scanned ' + counter.scanned + ' characters for ' + text.length + ' received');
});

test('the NDJSON parser scans each pushed chunk once', () => {
    const { api } = require('./query-load-more-harness.js').loadApi();
    const { text, chunks } = oversizedRecordChunks(16 * 1024);
    const seen = [];
    const parser = new api.NdjsonResultParser((record) => seen.push(record.type));
    const counter = countScans(api.consumeNdjsonResponse);
    try {
        chunks.forEach((chunk) => parser.push(chunk));
        parser.finish();
    } finally {
        counter.restore();
    }
    assert.deepEqual(seen, ['head', 'metadata', 'end']);
    assert.ok(counter.scanned < 3 * text.length,
        'scanned ' + counter.scanned + ' characters for ' + text.length + ' pushed');
});

// Review finding B24: the status line is rewritten every frame while rows stream in; as a live region it floods
// screen readers. Only the start, the end and failures are announced.
test('streaming rows announces only the start and the end, not every status update', async () => {
    const { api, document } = require('./query-load-more-harness.js').loadApi();
    const target = document.createElement('section');
    document.body.appendChild(target);
    const renderer = new api.QueryResultRenderer(target, { rowStore: memoryRowStore() });
    const liveTexts = () => renderer.root.querySelectorAll('[aria-live]')
        .concat(renderer.root.querySelectorAll('[role="status"]'))
        .map((element) => element.textContent);
    const announced = [];
    const record = () => liveTexts().forEach((text) => {
        if (text && announced[announced.length - 1] !== text) announced.push(text);
    });

    renderer.setBusy(true);
    record();
    await renderer.accept({ type: 'view', id: 'tuple' });
    await renderer.accept({ type: 'vars', values: ['value'] });
    for (let chunk = 0; chunk < 5; chunk++) {
        await renderer.accept({ type: 'rows', values: [[{ kind: 'literal', value: String(chunk) }]] });
        await settle();
        record();
    }
    await renderer.accept({ type: 'end', metadata: { 'total-result-count': 5 } });
    renderer.setBusy(false);
    await settle();
    record();

    assert.match(renderer.status.textContent, /5 rows · complete/);
    assert.deepEqual(announced, ['Receiving query results…', renderer.status.textContent],
        'one announcement when results start, one when they are complete');
    assert.equal(renderer.status.getAttribute('aria-live') ?? null, null, 'the status line is not a live region');
    assert.equal(renderer.status.getAttribute('role') ?? null, null);

    renderer.fail('The server stopped.');
    record();
    assert.equal(announced[announced.length - 1], renderer.status.textContent, 'a failure is announced');
    renderer.dispose();
});

// Review finding B26: a failure in the browser after rows arrived (the row store is full) is not the server's
// truncation: no timeout advice, and the server is told to stop the query it is still running.
test('a browser-side failure after rows is reported as such and cancels the server query', async () => {
    const { MemoryWorker } = require('./query-load-more-harness.js');
    class QuotaWorker extends MemoryWorker {
        postMessage(message) {
            if (message.op === 'append' && this.rows.length > 0) {
                this.messages.push(message);
                queueMicrotask(() => {
                    for (const callback of this.listeners.get('message') || []) {
                        callback({ data: { requestId: message.requestId, ok: false,
                            error: 'QuotaExceededError: The quota has been exceeded.' } });
                    }
                });
                return;
            }
            super.postMessage(message);
        }
    }
    const records = [
        { type: 'head', version: 1 }, { type: 'view', id: 'tuple' }, { type: 'vars', values: ['value'] },
        { type: 'rows', values: [[{ kind: 'literal', value: '0' }]] },
        { type: 'rows', values: [[{ kind: 'literal', value: '1' }]] },
        { type: 'end', metadata: { 'result-offset': 0, 'result-limit': 1000000, 'result-batch-count': 2,
            'result-has-more': false, 'result-next-offset': 2 } }
    ];
    const current = execution({ controls: { 'batch-size': null }, responses: [records] });
    // The harness's worker factory is replaced by one whose store fills up after the first rows.
    const { api } = current;
    const cancels = [];
    current.workbench.query = { cancelServerQuery: (id) => cancels.push(id) };
    const requests = [];
    const controller = api.bindMainQueryForm(current.form, current.target, {
        maxDomRows: 8,
        rowStoreOptions: { workerFactory: () => new QuotaWorker() },
        async fetcher(url, init) {
            requests.push(init);
            const { response } = require('./query-load-more-harness.js');
            return response(records);
        }
    });
    current.controller.dispose();
    controller.submit();
    await settle();
    const shown = current.target.querySelector('.ERROR').textContent;
    assert.match(shown, /quota/i, 'the browser\'s own error is shown');
    assert.doesNotMatch(shown, /increase the timeout|result stream ended/i, 'it is not presented as a server truncation');
    assert.doesNotMatch(current.target.querySelector('.query-result-status').textContent, /result stream ended/);
    assert.deepEqual(cancels, [requests[0].body.get('query-request-id')], 'the server query is cancelled');
    assert.equal(requests[0].signal.aborted, true, 'and the response is no longer read');
    controller.dispose();
});

// Review finding B27: a tab closed while a shelved query runs must cancel it with the keepalive request, the only
// one that outlives the page (the retrying jQuery request is dropped during unload).
test('closing the tab cancels a shelved running query with one keepalive request', async () => {
    const { workbench, document, window, MemoryWorker } = Object.assign(require('./query-load-more-harness.js').loadApi(),
        { MemoryWorker: require('./query-load-more-harness.js').MemoryWorker });
    heldQueryServer(window);
    const queryFetch = window.fetch;
    const keepalive = [];
    window.fetch = (url, init) => {
        if (init && init.keepalive) keepalive.push({ url, init });
        return queryFetch(url, init);
    };
    const pagehide = [];
    window.addEventListener = (type, listener) => { if (type === 'pagehide') pagehide.push(listener); };
    const retrying = [];
    workbench.query = { cancelServerQuery: (id) => retrying.push(id) };
    const form = document.createElement('form');
    form.setAttribute('id', 'query-form');
    form.setAttribute('action', 'query');
    const query = document.createElement('textarea');
    query.name = 'query';
    query.value = 'SELECT ?item WHERE { VALUES ?item { "row" } }';
    form.appendChild(query);
    const target = document.createElement('section');
    target.setAttribute('id', 'query-results');
    document.body.appendChild(form);
    document.body.appendChild(target);
    const dispose = workbench.queryPage.renderInto(document.body, {}, {
        executionFormId: 'query-form', resultsMountId: 'query-results', repositoryId: 'repo-a',
        rowStoreOptions: { workerFactory: () => new MemoryWorker() }
    });
    form.trigger('submit');
    await settle();
    dispose('navigate');
    assert.equal(workbench.queryPage.activity('repo-a'), 'running');

    pagehide.forEach((listener) => listener({ type: 'pagehide', persisted: false }));
    assert.deepEqual(retrying, [], 'no retrying request that the unload drops');
    const cancels = keepalive.filter((request) => /action=cancel-query/.test(String(request.init.body)));
    assert.equal(cancels.length, 1, 'one keepalive cancellation');
    assert.equal(cancels[0].init.method, 'POST');
});

test('Load more keeps the resolved options of options the original request carried', async () => {
    const first = withMetadata(batch([0, 1], 0, true), {
        'query-language': 'SPARQL', infer: false, 'query-timeout': 30
    });
    const current = execution({ controls: { infer: 'true', queryLn: 'sparql', 'query-timeout': '0' },
        responses: [first, batch([2, 3], 2, false)] });
    current.controller.submit();
    await settle();
    current.controller.loadMore();
    await settle();
    const body = current.requests[1].init.body;
    assert.equal(body.get('infer'), 'false');
    assert.equal(body.get('queryLn'), 'SPARQL');
    assert.equal(body.get('query-timeout'), '30');
    current.controller.dispose();
});

// Round 2 (R5): a continuation sent with the first batch's total (batch-known-total) may meet a result that changed
// since. Its has-more decides; the stale total is dropped (more follow) or replaced by the rows seen (it ended).
test('Load more after the result changed follows the continuation\'s has-more, not the stale total', async () => {
    const current = execution({ responses: [
        batch([0, 1], 0, true, { 'total-result-count': 6 }),
        // Shrunk: only one row left after offset 2, while the total still says 6.
        batch([2], 2, false, { 'total-result-count': 6 })
    ] });
    current.controller.submit();
    await settle();
    current.controller.loadMore();
    await settle();
    assert.equal(current.requests[1].init.body.get('batch-known-total'), '6');
    const status = current.target.querySelector('.query-result-status');
    assert.match(status.textContent, /^3 rows · complete/, status.textContent);
    assert.doesNotMatch(current.target.textContent, /Load more failed|Invalid Workbench query stream/);
    current.controller.dispose();

    const growing = execution({ responses: [
        batch([0, 1], 0, true, { 'total-result-count': 4 }),
        // More rows than the first total said: has-more stays true although the total equals the next offset.
        batch([2, 3], 2, true, { 'total-result-count': 4 })
    ] });
    growing.controller.submit();
    await settle();
    growing.controller.loadMore();
    await settle();
    assert.equal(growing.requests.length, 2);
    assert.doesNotMatch(growing.target.textContent, /Load more failed|Invalid Workbench query stream/);
    assert.equal(growing.target.querySelector('.query-result-load-more').hidden, false, 'Load more stays offered');
    growing.controller.dispose();
});

test('an empty continuation of a result that shrank below its offset completes with the rows shown', async () => {
    const current = execution({ responses: [
        batch([0, 1], 0, true, { 'total-result-count': 6, 'query-elapsed-ms': 2, 'query-result-status': 'completed' }),
        // Only one row is left: the continuation at offset 2 is empty and the total is below the rows shown.
        batch([], 2, false, { 'total-result-count': 1, 'query-elapsed-ms': 3, 'query-result-status': 'completed' })
    ] });
    current.controller.submit();
    await settle();
    current.controller.loadMore();
    await settle();
    const status = current.target.querySelector('.query-result-status');
    assert.match(status.textContent, /^2 rows · complete in 3 ms/, status.textContent);
    assert.doesNotMatch(current.target.textContent, /Load more failed|Invalid Workbench query stream/);
    current.controller.dispose();
});

test('the first batch still has to report a total that agrees with its has-more', async () => {
    const current = execution({ responses: [batch([0, 1], 0, true, { 'total-result-count': 2 })] });
    current.controller.submit();
    await settle();
    assert.match(current.target.textContent, /Invalid Workbench query stream: batch continuation metadata must match the exact total/);
    // R14: the server broke the protocol; the browser kept every row it was sent.
    assert.doesNotMatch(current.target.textContent, /browser could not keep|before the browser failed/);
    current.controller.dispose();
});
